[Form]
public class GUPAddPriceAttribute extends FormRun
{
    private FormRun                         sourceForm;
    private GUPPricingAttributeGroup        currentAttributeGroup;

    private GUPPricingAttributeGroupType    groupType;
    private GUPPricingAttributeSourceLevel  sourceLevel;
    private GUPPricingAttributeSource       currentSource;
    private str                             currentTable;

    private SysFormEnumComboBox             sourceComboBox;
   
}

    public void init()
    {
        xArgs args = element.args();

        if (!element.args().caller())
        {
            element.lifecycleHelper().cancelFormInitialization(Exception::Error, error::wrongUseOfFunction(funcName()));
        }
        else
        {
            sourceForm = args.caller();
            currentAttributeGroup = args.record();
            GUPPricingAttributeGroup = currentAttributeGroup;
            groupType = currentAttributeGroup.GroupType;
            sourceLevel = currentAttributeGroup.SourceLevel;
        }
        
        element.initControls();

        super(); 
           
        element.initPriceAttributeTmp();
        element.setControls();             
    }

    private void initControls()
    {
        Set enumSet = element.getSourceEnumForScope();

        if (groupType == GUPPricingAttributeGroupType::General)
        {            
            sourceComboBox = SysFormEnumComboBox::newParameters(
                    element,
                    element.controlId(formControlStr(GUPAddPriceAttribute, PricingAttributeGroup_GroupType)),
                    enumnum(GUPPricingAttributeSource),
                    enumSet,
                    "@GlobalUnifiedPricing:GUPPricingAttributeSourceName");
        }
    }

    private void setControls()
    {
        PricingAttributeGroup_SourceLevel.allowEdit(false);
        PricingAttributeGroup_SourceLevel.text(enum2Str(sourceLevel));
       
        switch (groupType)
        {
            case GUPPricingAttributeGroupType::Customer:
                PricingAttributeGroup_GroupType.allowEdit(false);
                PricingAttributeGroup_GroupType.selection(enum2int(GUPPricingAttributeSource::Customer));
                currentSource = GUPPricingAttributeSource::Customer;
                break;

            case GUPPricingAttributeGroupType::Product:
                PricingAttributeGroup_GroupType.allowEdit(false);
                PricingAttributeGroup_GroupType.selection(enum2int(GUPPricingAttributeSource::Product));
                currentSource = GUPPricingAttributeSource::Product;
                break; 
          
            default:
                if (sourceLevel == GUPPricingAttributeSourceLevel::Header)
                {
                    sourceComboBox.select(enum2int(GUPPricingAttributeSource::Customer));
                    currentSource = GUPPricingAttributeSource::Customer;
                }
                else if (sourceLevel == GUPPricingAttributeSourceLevel::Line)
                {
                    sourceComboBox.select(enum2int(GUPPricingAttributeSource::Product));
                    currentSource = GUPPricingAttributeSource::Product;
                }
        }       
    }

    private Set getSourceEnumForScope()
    {
        Set enumSet = new Set(Types::Enum);
        switch (sourceLevel)
        {
            case GUPPricingAttributeSourceLevel::Header:
                enumSet.add(GUPPricingAttributeSource::Customer);
                enumSet.add(GUPPricingAttributeSource::CustomerPriceGroup);
                enumSet.add(GUPPricingAttributeSource::SalesTable);                
                break;

            case GUPPricingAttributeSourceLevel::Line:
                enumSet.add(GUPPricingAttributeSource::Product);
                enumSet.add(GUPPricingAttributeSource::ProductPriceGroup);
                enumSet.add(GUPPricingAttributeSource::SalesLine);
                break;
        }
        return enumSet;
    }

    private void initPriceAttributeTmp()
    {
        select firstonly RecId from GUPPricingAttributeTmp;
        if (!GUPPricingAttributeTmp.RecId)
        {
            List attributes = GUPPricingAttributeRepository::getAllPricingAttributes();

            ttsbegin;

            Enumerator enum = attributes.getEnumerator();

            GUPIPricingAttribute pricingAttr;
            GUPPricingAttributeLink link;
            GUPPricingAttributeSourceDiscoveryAttribute discoveryAttributeAsObject;
            int cnt = 1;

            while (enum.moveNext())
            {
                pricingAttr = enum.current();
                link = GUPPricingAttributeRepository::toPriceAttributeLink(pricingAttr);
                GUPPricingAttributeTmp.AttributeName = link.AttributeName;
                GUPPricingAttributeTmp.PriceAttributeClassId = link.PriceAttributeClassId;
                GUPPricingAttributeTmp.TypeName = link.TypeName;
                GUPPricingAttributeTmp.ProviderClassId = link.AttributeProviderClassId;
                GUPPricingAttributeTmp.Id = cnt;

                discoveryAttributeAsObject =
                    GUPPricingAttributeRepository::getPricingAttributeAttributeAsObject(
                        pricingAttr,
                        attributeStr(GUPPricingAttributeSourceDiscoveryAttribute));

                GUPPricingAttributeTmp.Level = discoveryAttributeAsObject.parmLevel();
                GUPPricingAttributeTmp.Source = discoveryAttributeAsObject.parmSource();

                GUPPricingAttributeTmp.Table = pricingAttr.getQueryBuilderDatasourceIdentifier();
                GUPPricingAttributeTmp.PriceAttributeClassName = classId2Name(link.PriceAttributeClassId);
                GUPPricingAttributeTmp.insert();
                cnt++;
            }
            ttscommit;
        }
    }

        public void executeQuery()
        {
            Query query = new Query();
            QueryBuildDataSource        queryBuildDataSource;
            QueryBuildRange             queryBuildRange;
            QueryBuildRange             queryBuildRangeSource;
   
            queryBuildDataSource = query.addDataSource(tablenum(GUPPricingAttributeTmp));
            queryBuildDataSource.addSortField(fieldNum(GUPPricingAttributeTmp, AttributeName));

            // Filter by SourceLevel
            queryBuildRange = queryBuildDataSource.addRange(fieldNum(GUPPricingAttributeTmp, Level));
            queryBuildRange.value(PricingAttributeGroup_SourceLevel.valueStr());

            // Filter by GroupType
            switch (groupType)
            {
                case GUPPricingAttributeGroupType::Customer:
                    queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(GUPPricingAttributeTmp, Source));
                    queryBuildRangeSource.value(enum2Symbol(enumNum(GUPPricingAttributeSource), GUPPricingAttributeSource::Customer));
                    break;

                case GUPPricingAttributeGroupType::Product:
                    queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(GUPPricingAttributeTmp, Source));
                    queryBuildRangeSource.value(enum2Symbol(enumNum(GUPPricingAttributeSource), GUPPricingAttributeSource::Product));
                    break;

                case GUPPricingAttributeGroupType::General:
                    queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(GUPPricingAttributeTmp, Source));
                    queryBuildRangeSource.value(enum2Symbol(enumNum(GUPPricingAttributeSource), element.currentSource));
            }

            if(element.currentTable)
            {
                queryBuildRangeSource = queryBuildDataSource.addRange(fieldNum(GUPPricingAttributeTmp, Table));
                queryBuildRangeSource.value(element.currentTable);
            }

            this.query(query);
            super();
        }

        public boolean modified()
        {
            boolean ret;

            ret = super();
       
            GUPPricingAttributeSource sourceType;
            element.currentSource = str2Enum(sourceType, this.valueStr());

            PricingAttributeGroup_Table.text('');
            element.currentTable = '';

            GUPPricingAttributeTmp_ds.executeQuery();

            return ret;
        }

        public void lookup()
        {
            SysTableLookup sysTableLookup = SysTableLookup::newParameters(tableNum(GUPPricingAttributeTmp), this);
            Query query = new Query();

            QueryBuildDataSource qbdsGroup = query.addDataSource(tableNum(GUPPricingAttributeTmp));
            qbdsGroup.addRange(fieldNum(GUPPricingAttributeTmp, Level)).value(any2Str(element.sourceLevel));
            qbdsGroup.addRange(fieldNum(GUPPricingAttributeTmp, Source)).value(enum2Symbol(enumNum(GUPPricingAttributeSource), element.currentSource));

            qbdsGroup.addGroupByField(fieldNum(GUPPricingAttributeTmp, Table));
            qbdsGroup.orderMode(OrderMode::GroupBy);
            sysTableLookup.addLookupfield(fieldNum(GUPPricingAttributeTmp, Table));

            sysTableLookup.parmQuery(query);
            sysTableLookup.parmTmpBuffer(GUPPricingAttributeTmp);
            sysTableLookup.performFormLookup();

            super();
        }

        public boolean modified()
        {
            boolean ret;

            ret = super();
       
            element.currentTable = this.valueStr();

            GUPPricingAttributeTmp_ds.executeQuery();

            return ret;
        }

        public void clicked()
        {
            super();

            if (GUPPricingAttributeGroup::isPricingAttributeGroupUsed(currentAttributeGroup.RecId))
            {
                warning("@GlobalUnifiedPricing:GUPPricingAttributeGroupIsUsed");
                return;
            }

            ttsbegin; 

            GUPPricingAttributeTmp  attributeTmp;
            GUPPricingAttributeLink link;
            
            int priority = this.getHighestPriority();

            for (attributeTmp = GUPPricingAttributeTmp_ds.getFirst(true) ? GUPPricingAttributeTmp_ds.getFirst(true) : GUPPricingAttributeTmp_ds.cursor();
                 attributeTmp;
                 attributeTmp = GUPPricingAttributeTmp_ds.getNext())
            {
                link.PriceAttributeGroup      = currentAttributeGroup.RecId;
                link.PriceAttributeClassId    = attributeTmp.PriceAttributeClassId;
                link.AttributeName            = attributeTmp.AttributeName;
                link.AttributeProviderClassId = attributeTmp.ProviderClassId;
                link.TypeName                 = attributeTmp.TypeName;
                link.Source                   = attributeTmp.Source;
                link.Priority                 = priority;

                link.initFromPricingAttribute(link.pricingAttribute());

                link.AttributeSourceType      = GUPPricingAttributeSourceType::Table;
                link.insert();
                
                priority++;
            }
            
            ttscommit;         
        }

public int getHighestPriority()
{
    GUPPricingAttributeLink link;
    select firstonly Priority from link order by Priority desc
        where link.PriceAttributeGroup == GUPPricingAttributeLink.PriceAttributeGroup;
    return link.Priority + 1;
}
